import React, { useEffect, useRef, useState } from 'react';
import api from '../services/api';

/*
  AdminCharts — Section statistiques visuelles du Dashboard Admin EduMatch
  ─────────────────────────────────────────────────────────────────────────
  Graphiques :
  1. Réservations par mois (line chart — 6 derniers mois)
  2. Réservations par matière top 6 (bar chart horizontal)
  3. Répartition mode d'enseignement (donut chart)
  4. Statut des professeurs (donut chart)
  ─────────────────────────────────────────────────────────────────────────
  Utilise Chart.js via CDN (déjà disponible dans les artifacts Claude)
  Import : import AdminCharts from './AdminCharts';
*/

// ── Charger Chart.js dynamiquement ──────────────────────────────
let chartJsLoaded = false;
function loadChartJs() {
  return new Promise((resolve) => {
    if (window.Chart) { resolve(window.Chart); return; }
    if (chartJsLoaded) {
      const wait = setInterval(() => {
        if (window.Chart) { clearInterval(wait); resolve(window.Chart); }
      }, 50);
      return;
    }
    chartJsLoaded = true;
    const s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js';
    s.onload = () => resolve(window.Chart);
    document.head.appendChild(s);
  });
}

// ── Couleurs EduMatch ────────────────────────────────────────────
const COLORS = {
  purple:  '#6c63ff',
  pink:    '#ff6584',
  green:   '#43e97b',
  blue:    '#38bdf8',
  orange:  '#f59e0b',
  red:     '#ef4444',
  teal:    '#14b8a6',
  indigo:  '#818cf8',
};
const COLOR_LIST = Object.values(COLORS);

// ── Hook pour un canvas Chart.js ────────────────────────────────
function useChart(canvasRef, buildConfig, deps) {
  const chartRef = useRef(null);
  useEffect(() => {
    if (!canvasRef.current) return;
    loadChartJs().then((Chart) => {
      if (chartRef.current) chartRef.current.destroy();
      const ctx = canvasRef.current.getContext('2d');
      chartRef.current = new Chart(ctx, buildConfig(Chart));
    });
    return () => { if (chartRef.current) chartRef.current.destroy(); };
  }, deps);
}

// ════════════════════════════════════════════════
//  GRAPHIQUE 1 — Réservations par mois (line)
// ════════════════════════════════════════════════
function ChartReservationsMois({ data }) {
  const ref = useRef(null);

  useChart(ref, (Chart) => ({
    type: 'line',
    data: {
      labels: data.map(d => d.mois),
      datasets: [{
        label: 'Réservations',
        data: data.map(d => d.total),
        borderColor: COLORS.purple,
        backgroundColor: 'rgba(108,99,255,0.12)',
        borderWidth: 2.5,
        fill: true,
        tension: 0.45,
        pointBackgroundColor: COLORS.purple,
        pointRadius: 5,
        pointHoverRadius: 7,
      }],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: '#1e293b',
          titleColor: '#94a3b8',
          bodyColor: '#fff',
          borderColor: '#334155',
          borderWidth: 1,
          callbacks: {
            label: ctx => ` ${ctx.parsed.y} réservation${ctx.parsed.y > 1 ? 's' : ''}`,
          },
        },
      },
      scales: {
        x: {
          grid: { color: 'rgba(255,255,255,0.04)' },
          ticks: { color: '#64748b', font: { size: 11 } },
        },
        y: {
          beginAtZero: true,
          grid: { color: 'rgba(255,255,255,0.04)' },
          ticks: { color: '#64748b', font: { size: 11 }, stepSize: 1 },
        },
      },
    },
  }), [data]);

  return <canvas ref={ref} />;
}

// ════════════════════════════════════════════════
//  GRAPHIQUE 2 — Réservations par matière (bar)
// ════════════════════════════════════════════════
function ChartMatieres({ data }) {
  const ref = useRef(null);

  useChart(ref, (Chart) => ({
    type: 'bar',
    data: {
      labels: data.map(d => d.matiere),
      datasets: [{
        label: 'Cours',
        data: data.map(d => d.total),
        backgroundColor: data.map((_, i) => COLOR_LIST[i % COLOR_LIST.length] + 'cc'),
        borderColor:     data.map((_, i) => COLOR_LIST[i % COLOR_LIST.length]),
        borderWidth: 1.5,
        borderRadius: 6,
      }],
    },
    options: {
      indexAxis: 'y',   // Barres horizontales
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: '#1e293b',
          titleColor: '#94a3b8',
          bodyColor: '#fff',
          borderColor: '#334155',
          borderWidth: 1,
        },
      },
      scales: {
        x: {
          beginAtZero: true,
          grid: { color: 'rgba(255,255,255,0.04)' },
          ticks: { color: '#64748b', font: { size: 11 }, stepSize: 1 },
        },
        y: {
          grid: { display: false },
          ticks: { color: '#e2e8f0', font: { size: 12, weight: '500' } },
        },
      },
    },
  }), [data]);

  return <canvas ref={ref} />;
}

// ════════════════════════════════════════════════
//  GRAPHIQUE 3 — Mode d'enseignement (donut)
// ════════════════════════════════════════════════
function ChartModes({ data }) {
  const ref = useRef(null);

  useChart(ref, (Chart) => ({
    type: 'doughnut',
    data: {
      labels: data.map(d => d.label),
      datasets: [{
        data: data.map(d => d.val),
        backgroundColor: [COLORS.purple, COLORS.blue, COLORS.green],
        borderColor: '#0f172a',
        borderWidth: 3,
        hoverOffset: 8,
      }],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      cutout: '68%',
      plugins: {
        legend: {
          position: 'bottom',
          labels: {
            color: '#94a3b8',
            font: { size: 11 },
            padding: 16,
            usePointStyle: true,
            pointStyleWidth: 8,
          },
        },
        tooltip: {
          backgroundColor: '#1e293b',
          titleColor: '#94a3b8',
          bodyColor: '#fff',
          borderColor: '#334155',
          borderWidth: 1,
          callbacks: {
            label: ctx => ` ${ctx.label} : ${ctx.parsed} prof${ctx.parsed > 1 ? 's' : ''}`,
          },
        },
      },
    },
  }), [data]);

  return <canvas ref={ref} />;
}

// ════════════════════════════════════════════════
//  GRAPHIQUE 4 — Statut des professeurs (donut)
// ════════════════════════════════════════════════
function ChartStatutProfs({ data }) {
  const ref = useRef(null);

  useChart(ref, (Chart) => ({
    type: 'doughnut',
    data: {
      labels: data.map(d => d.label),
      datasets: [{
        data: data.map(d => d.val),
        backgroundColor: [COLORS.green, COLORS.orange, COLORS.red],
        borderColor: '#0f172a',
        borderWidth: 3,
        hoverOffset: 8,
      }],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      cutout: '68%',
      plugins: {
        legend: {
          position: 'bottom',
          labels: {
            color: '#94a3b8',
            font: { size: 11 },
            padding: 16,
            usePointStyle: true,
            pointStyleWidth: 8,
          },
        },
        tooltip: {
          backgroundColor: '#1e293b',
          titleColor: '#94a3b8',
          bodyColor: '#fff',
          borderColor: '#334155',
          borderWidth: 1,
          callbacks: {
            label: ctx => ` ${ctx.label} : ${ctx.parsed} prof${ctx.parsed > 1 ? 's' : ''}`,
          },
        },
      },
    },
  }), [data]);

  return <canvas ref={ref} />;
}

// ════════════════════════════════════════════════
//  CARTE CONTENEUR
// ════════════════════════════════════════════════
function ChartCard({ title, subtitle, icon, children, height = 260, style = {} }) {
  return (
    <div style={{
      background: 'var(--surface)',
      border: '1px solid var(--border)',
      borderRadius: 20,
      padding: '22px 24px',
      display: 'flex',
      flexDirection: 'column',
      gap: 16,
      ...style,
    }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
            <span style={{ fontSize: '1.1rem' }}>{icon}</span>
            <span style={{ fontFamily: 'Syne, sans-serif', fontWeight: 700, fontSize: '.95rem', color: 'var(--text)' }}>{title}</span>
          </div>
          {subtitle && <div style={{ fontSize: '.75rem', color: 'var(--text2)' }}>{subtitle}</div>}
        </div>
      </div>
      <div style={{ height, position: 'relative' }}>
        {children}
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════
//  COMPOSANT PRINCIPAL
// ════════════════════════════════════════════════
export default function AdminCharts({ stats = {}, allProfs = [] }) {
  const [chartData, setChartData] = useState(null);
  const [loading, setLoading]     = useState(true);

  useEffect(() => {
    api.get('/api/admin/stats/charts')
      .then(res => {
        const cd = res.data;

        // ── Réservations par mois : données RÉELLES depuis BDD ──
        const reservationsMois = (cd.reservations_par_mois && cd.reservations_par_mois.length > 0)
          ? cd.reservations_par_mois
          : genFakeMonths();   // fallback si BDD vide (pas de réservations encore)

        // ── Matières les plus demandées : données RÉELLES ────────
        const matieres = (cd.matieres_populaires && cd.matieres_populaires.length > 0)
          ? cd.matieres_populaires
          : genFakeMatieres(); // fallback si 0 réservation encore

        // ── Mode d'enseignement depuis allProfs (déjà chargé) ────
        const nbLigne     = allProfs.filter(p => p.mode_enseignement === 'en_ligne').length;
        const nbPres      = allProfs.filter(p => p.mode_enseignement === 'presentiel').length;
        const nbDeuxModes = allProfs.filter(p => p.mode_enseignement === 'les_deux').length;

        // ── Statut des professeurs depuis allProfs ────────────────
        const nbValide  = allProfs.filter(p => p.statut_validation === 'validé').length;
        const nbAttente = allProfs.filter(p => p.statut_validation === 'en_attente').length;
        const nbRefuse  = allProfs.filter(p => p.statut_validation === 'refusé').length;

        setChartData({
          reservationsMois,
          matieres,
          isRealData: cd.reservations_par_mois?.length > 0,
          modes: [
            { label: '🌐 En ligne',   val: nbLigne     },
            { label: '🏫 Présentiel', val: nbPres      },
            { label: '🔀 Les deux',   val: nbDeuxModes },
          ].filter(m => m.val > 0),
          statutProfs: [
            { label: '✅ Validés',    val: nbValide  },
            { label: '⏳ En attente', val: nbAttente },
            { label: '❌ Refusés',    val: nbRefuse  },
          ].filter(s => s.val > 0),
        });
        setLoading(false);
      })
      .catch(err => {
        console.error('[AdminCharts] Erreur API:', err);
        // En cas d'erreur réseau totale → données de démo
        const nbLigne     = allProfs.filter(p => p.mode_enseignement === 'en_ligne').length;
        const nbPres      = allProfs.filter(p => p.mode_enseignement === 'presentiel').length;
        const nbDeuxModes = allProfs.filter(p => p.mode_enseignement === 'les_deux').length;
        const nbValide    = allProfs.filter(p => p.statut_validation === 'validé').length;
        const nbAttente   = allProfs.filter(p => p.statut_validation === 'en_attente').length;
        const nbRefuse    = allProfs.filter(p => p.statut_validation === 'refusé').length;
        setChartData({
          reservationsMois: genFakeMonths(),
          matieres:         genFakeMatieres(),
          isRealData:       false,
          modes: [
            { label: '🌐 En ligne',   val: nbLigne     },
            { label: '🏫 Présentiel', val: nbPres      },
            { label: '🔀 Les deux',   val: nbDeuxModes },
          ].filter(m => m.val > 0),
          statutProfs: [
            { label: '✅ Validés',    val: nbValide  },
            { label: '⏳ En attente', val: nbAttente },
            { label: '❌ Refusés',    val: nbRefuse  },
          ].filter(s => s.val > 0),
        });
        setLoading(false);
      });
  }, [allProfs.length]);

  if (loading) {
    return (
      <div style={{ padding: '40px', textAlign: 'center', color: 'var(--text2)' }}>
        <div style={{ fontSize: '1.5rem', marginBottom: 8 }}>📊</div>
        Chargement des statistiques...
      </div>
    );
  }

  const totalModes = chartData.modes.reduce((a, b) => a + b.val, 0);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>

      {/* ── Titre section ── */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 4 }}>
        <div style={{ width: 4, height: 24, background: 'linear-gradient(180deg,#6c63ff,#ff6584)', borderRadius: 2 }} />
        <div>
          <h2 style={{ fontFamily: 'Syne, sans-serif', fontSize: '1.1rem', fontWeight: 800, margin: 0, color: 'var(--text)' }}>
            Statistiques & Analyses
          </h2>
          <p style={{ fontSize: '.75rem', color: 'var(--text2)', margin: 0 }}>Vue d'ensemble de l'activité EduMatch</p>
        </div>
      </div>

      {/* ── Ligne 1 : 2 grands graphiques ── */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>

        {/* Graphique 1 — Réservations par mois */}
        <ChartCard
          icon="📈"
          title="Réservations par mois"
          subtitle={chartData.isRealData
            ? "✅ Données réelles — 6 derniers mois"
            : "⚠️ Données de démonstration (aucune réservation encore)"}
          height={240}
        >
          <ChartReservationsMois data={chartData.reservationsMois} />
        </ChartCard>

        {/* Graphique 2 — Top matières */}
        <ChartCard
          icon="📚"
          title="Matières les plus demandées"
          subtitle={chartData.isRealData
            ? "✅ Données réelles — basées sur les réservations"
            : "⚠️ Données de démonstration (aucune réservation encore)"}
          height={240}
        >
          <ChartMatieres data={chartData.matieres} />
        </ChartCard>
      </div>

      {/* ── Ligne 2 : 2 petits donuts + mini stats ── */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 16 }}>

        {/* Graphique 3 — Mode d'enseignement */}
        <ChartCard
          icon="🌐"
          title="Mode d'enseignement"
          subtitle={`${totalModes} professeurs au total`}
          height={200}
        >
          {chartData.modes.length > 0 ? (
            <ChartModes data={chartData.modes} />
          ) : (
            <EmptyChart msg="Aucun professeur validé" />
          )}
        </ChartCard>

        {/* Graphique 4 — Statut des profs */}
        <ChartCard
          icon="👨‍🏫"
          title="Statut des professeurs"
          subtitle="Répartition validation"
          height={200}
        >
          {chartData.statutProfs.length > 0 ? (
            <ChartStatutProfs data={chartData.statutProfs} />
          ) : (
            <EmptyChart msg="Aucun professeur enregistré" />
          )}
        </ChartCard>

        {/* Mini KPIs textuels */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {[
            {
              icon: '🏆',
              label: 'Taux de validation',
              val: chartData.statutProfs.length > 0
                ? Math.round((chartData.statutProfs.find(s => s.label.includes('Validés'))?.val || 0) /
                  chartData.statutProfs.reduce((a, b) => a + b.val, 0) * 100)
                : 0,
              suffix: '%',
              color: '#43e97b',
            },
            {
              icon: '📅',
              label: 'Réservations ce mois',
              val: stats.reservations_mois || 0,
              suffix: '',
              color: '#6c63ff',
            },
            {
              icon: '⏳',
              label: 'Profils en attente',
              val: stats.en_attente || 0,
              suffix: '',
              color: '#f59e0b',
            },
            {
              icon: '📬',
              label: 'Demandes matières',
              val: stats.demandes_matieres_pending || 0,
              suffix: '',
              color: '#38bdf8',
            },
          ].map((kpi, i) => (
            <div key={i} style={{
              background: 'var(--surface)',
              border: '1px solid var(--border)',
              borderRadius: 14,
              padding: '14px 18px',
              display: 'flex',
              alignItems: 'center',
              gap: 14,
              flex: 1,
            }}>
              <div style={{ width: 38, height: 38, borderRadius: 10, background: kpi.color + '18', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.1rem', flexShrink: 0 }}>
                {kpi.icon}
              </div>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontFamily: 'Syne, sans-serif', fontWeight: 800, fontSize: '1.3rem', color: kpi.color, lineHeight: 1 }}>
                  {kpi.val}{kpi.suffix}
                </div>
                <div style={{ fontSize: '.72rem', color: 'var(--text2)', marginTop: 3, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {kpi.label}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

// ── Message si pas de données ────────────────────────────────────
function EmptyChart({ msg }) {
  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', color: 'var(--text2)', fontSize: '.8rem', gap: 8 }}>
      <span style={{ fontSize: '1.8rem' }}>📭</span>
      {msg}
    </div>
  );
}

// ── Données de démo si l'API /charts n'existe pas encore ─────────
function genFakeMonths() {
  const mois = ['Nov', 'Déc', 'Jan', 'Fév', 'Mar', 'Avr'];
  return mois.map((m, i) => ({ mois: m, total: [2, 4, 3, 6, 5, 8][i] || 0 }));
